use std::io::*;

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut out = String::new();
    for line in s.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        if p.len() < 3 {
            continue;
        }
        let f: u128 = p[1].parse().unwrap();
        let t: u128 = p[2].parse().unwrap();
        let mut v: u128 = 0;
        for c in p[0].chars() {
            let d = c.to_digit(36).unwrap() as u128;
            v = v * f + d;
        }
        if v == 0 {
            out.push_str("0\n");
            continue;
        }
        let mut r = Vec::new();
        while v > 0 {
            r.push(std::char::from_digit((v % t) as u32, 36).unwrap().to_ascii_uppercase());
            v /= t;
        }
        out.extend(r.iter().rev());
        out.push('\n');
    }
    print!("{}", out);
}

